import math
    import random
    import time

    LANGUAGE_WRAPPER = "A rectangular field measures {width} by {height} meters and is already fenced along its outer boundary. Internal fences may be built only parallel to the field's sides. The field must be completely partitioned into congruent rectangular test plots whose side lengths are in the fixed ratio {p}:{q}, with the side corresponding to {p} aligned along the {width}-meter direction and the side corresponding to {q} aligned along the {height}-meter direction. Each meter of vertical internal fence (running the full {height} meters) consumes {c_v} units of material, and each meter of horizontal internal fence (running the full {width} meters) consumes {c_h} units of material. Up to {fence_units} units of material are available for internal fencing, and any amount up to this total may be used. What is the largest number of test plots that can be formed under these constraints? Provide your answer as an integer."

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
import math
# We parametrize A=width=g*x and B=height=g*y with gcd(x,y)=1 to enable a clean grid family.
# We also set an aspect ratio p:q (coprime), and anisotropic costs c_v!=c_h.
# Then we pick k* so that the budget lies in [L(k*), L(k*+1)-1], ensuring the maximum is achieved at k*.
for _ in range(1000):
    x = rng.randint(2, 16)
    y = rng.randint(2, 16)
    if math.gcd(x, y) != 1:
        continue
    g = rng.randint(3, 40)
    # choose p,q coprime; prefer non-square ratios often
    for _pq in range(100):
        p = rng.randint(1, 5)
        q = rng.randint(1, 5)
        if math.gcd(p, q) == 1:
            # encourage non-square and avoid triviality
            if p == 1 and q == 1 and rng.random() < 0.6:
                continue
            break
    else:
        continue
    # anisotropic costs
    c_v = rng.randint(1, 5)
    c_h = rng.randint(1, 5)
    if c_v == c_h:
        if rng.random() < 0.7:
            continue
    A = g * x
    B = g * y
    # pick a target k*
    k_star = rng.randint(2, 8)
    gap = g * x * y * (c_v * q + c_h * p)  # L(k+1)-L(k)
    F_min = g * k_star * x * y * (c_v * q + c_h * p) - g * (c_v * y + c_h * x)
    if F_min < 1:
        continue
    # Select fence_units in [F_min, F_min + gap - 1]
    fence_units = F_min + rng.randint(0, max(0, gap - 1))
    # Sanity: computed k via formula must equal k_star
    k_calc = (fence_units + g * (c_v * y + c_h * x)) // gap
    if k_calc != k_star:
        continue
    return {
        'width': A,
        'height': B,
        'fence_units': fence_units,
        'c_v': c_v,
        'c_h': c_h,
        'p': p,
        'q': q
    }
# Fallback deterministic instance if random fails
# Construct a safe instance manually
x, y, g = 5, 7, 6
p, q = 2, 1
c_v, c_h = 3, 1
A = g * x
B = g * y
gap = g * x * y * (c_v * q + c_h * p)
k_star = 3
F_min = g * k_star * x * y * (c_v * q + c_h * p) - g * (c_v * y + c_h * x)
fence_units = F_min + 1
return {
    'width': A,
    'height': B,
    'fence_units': fence_units,
    'c_v': c_v,
    'c_h': c_h,
    'p': p,
    'q': q
}

    def verifier(assign):
import math
# Validate domain constraints
try:
    A = int(assign['width'])
    B = int(assign['height'])
    F = int(assign['fence_units'])
    c_v = int(assign['c_v'])
    c_h = int(assign['c_h'])
    p = int(assign['p'])
    q = int(assign['q'])
except Exception:
    # Invalid types
    return (False, None)
if not (A > 0 and B > 0 and F > 0 and c_v > 0 and c_h > 0 and p > 0 and q > 0):
    return (False, None)
g = math.gcd(A, B)
x = A // g
y = B // g
if A != g * x or B != g * y or math.gcd(x, y) != 1:
    # Must decompose cleanly
    return (False, None)
if math.gcd(p, q) != 1:
    # Aspect ratio must be in lowest terms
    return (False, None)
# Enforce non-triviality/difficulty: at least one of (p != q) or (c_v != c_h)
if (p == q) and (c_v == c_h):
    return (False, None)
# Cost increment per unit k
gap = g * x * y * (c_v * q + c_h * p)
if gap <= 0:
    return (False, None)
# Compute maximal feasible k
# Derived from L(k) = g*k*x*y*(c_v*q + c_h*p) - g*(c_v*y + c_h*x)
# Constraint: L(k) <= F
# Solve for k: k <= (F + g*(c_v*y + c_h*x)) / gap
k_max = (F + g * (c_v * y + c_h * x)) // gap
if k_max < 1:
    # Not enough material for even k=1 tiling
    return (False, None)
# Verify tightness to ensure instance is not trivial/easy: L(k_max) <= F < L(k_max+1)
def L(k):
    return g * k * x * y * (c_v * q + c_h * p) - g * (c_v * y + c_h * x)
if not (L(k_max) <= F and F < L(k_max + 1)):
    # The provided budget does not isolate a unique maximal k, reducing intended difficulty
    return (False, None)
# Number of plots is a*b with a = k*x*q and b = k*y*p
answer = (k_max ** 2) * x * y * p * q
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

